// Build one digest email out of the new articles.
const escapeHtml = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const articles = $('Keep only new articles').all().map(item => item.json);
const lines = articles.map(article => {
  const date = article.date ? ` (${escapeHtml(article.date)})` : '';
  return `<li><a href="${escapeHtml(article.url)}">${escapeHtml(article.title)}</a>${date}</li>`;
});
const count = articles.length;

return [{ json: {
  subject: `${count} new article${count === 1 ? '' : 's'} on your watched page`,
  html: `<p>New articles since the last check:</p>\n<ul>\n${lines.join('\n')}\n</ul>`
} }];

// The Gaffa request body. Change the fields here if you want other data from the page.
const gaffaBody = {
  url: $('Settings').first().json.page_url,
  max_cache_age: 0,
  settings: {
    time_limit: 60000,
    actions: [
      {
        type: 'parse_json',
        selector: $('Settings').first().json.list_selector,
        output_type: 'inline',
        data_schema: {
          name: 'article_list',
          description: 'The articles listed on the page',
          fields: [
            {
              type: 'array',
              name: 'articles',
              description: 'One entry per article in the list',
              fields: [
                { type: 'string', name: 'title', description: 'The article title' },
                { type: 'string', name: 'url', description: 'The absolute link to the article' },
                {
                  type: 'string',
                  name: 'date',
                  description: 'The publication date or age as shown, empty string when the page shows none',
                },
              ],
            },
          ],
        },
      },
    ],
  },
};

return [{ json: { gaffaBody } }];
